# Create Synced Table for low-latency feature access
from databricks.sdk import WorkspaceClient
import requests
import json

# WorkspaceClient auto-discovers auth in serverless context
w = WorkspaceClient()
HOST = w.config.host
TOKEN = w.config.token

results = {"host": HOST, "token_ok": TOKEN is not None and len(TOKEN) > 0}

headers = {
    'Authorization': f'Bearer {TOKEN}',
    'Content-Type': 'application/json'
}

payload = {
    "name": "workspace.mlpab0d6714.scaled7ecfaf",
    "spec": {
        "source_table_full_name": "workspace.mlpab0d6714.scaled7ecfaf",
        "primary_key_columns": ["row_id"],
        "run_triggered": {}
    }
}

# Try multiple API paths for Synced Tables
paths = [
    "/api/2.0/catalog/synced-tables",
    "/api/2.1/catalog/synced-tables",
    "/api/2.0/delta-sync/synced-tables",
    "/api/2.0/feature-engineering/feature-tables",
    "/api/2.0/online-tables",
]

for path in paths:
    url = f"{HOST}{path}"
    resp = requests.post(url, headers=headers, json=payload)
    results[path] = {"status": resp.status_code, "body": resp.text[:200]}

dbutils.notebook.exit(json.dumps(results))

